use vstd::prelude::*;
use vstd::vec::*;

verus! {

fn reverse(a: &mut Vec<i32>) 
    ensures
        a.len() == old(a).len(),
        forall|i: int| 0 <= i < a.len() ==> a[i] == old(a)[a.len() - 1 - i],
{
    let original_len = a.len();
    let mut left: usize = 0;
    let mut right: usize = if original_len == 0 { 0 } else { original_len - 1 };
    
    while left < right
        invariant
            // Bounds
            0 <= left <= right < original_len || (original_len == 0 && left == 0 && right == 0),
            // Length unchanged
            a.len() == original_len,
            // Elements swapped so far
            forall|i: int| 0 <= i < left ==> a[i] == old(a)[original_len - 1 - i],
            forall|i: int| right < i < original_len ==> a[i] == old(a)[original_len - 1 - i],
            // Middle elements unchanged (not yet processed)
            forall|i: int| left <= i <= right ==> a[i] == old(a)[i],
            // Symmetry: elements at mirrored positions are swapped
            forall|i: int, j: int| 
                0 <= i < left && right < j < original_len && i == original_len - 1 - j ==>
                    a[i] == old(a)[j] && a[j] == old(a)[i],
        decreases
            right - left,
    {
        // Swap elements at left and right indices
        let temp = a[left];
        a[left] = a[right];
        a[right] = temp;
        
        // Update indices
        left = left + 1;
        right = right - 1;
    }
}

}
